package com.danawa.search.analysis.product.rule;

import com.danawa.search.analysis.dict.*;
import com.danawa.search.analysis.korean.KoreanWordExtractor;
import com.danawa.search.analysis.product.AnalyzerOption;
import com.danawa.util.CharVector;
import org.apache.logging.log4j.LogManager;
import org.apache.logging.log4j.Logger;

import java.util.List;
import java.util.Objects;

import static com.danawa.search.analysis.product.ProductNameTokenizer.*;

public abstract class Rule {
    protected static final Logger logger = LogManager.getLogger(Rule.class);

    //초기 분석 상태.
    protected Entry entry;
    //풀텀 분석결과 포함 여부
    protected final boolean fullExtract;
    //분석 옵션
    protected AnalyzerOption option;

    protected KoreanWordExtractor extractor;

    protected SetDictionary unitDictionary;
    protected SpaceDictionary spaceDictionary;
    protected SynonymDictionary unitSynonymDictionary;
    protected SetDictionary userDictionary;
    protected CompoundDictionary compoundDictionary;
    protected SetDictionary stopDictionary;

    public Rule(Entry entry, boolean fullExtract, AnalyzerOption option) {
        this.entry = entry;
        this.fullExtract = fullExtract;
        this.option = option;
    }

    abstract public void apply(List<RuleEntry> queue);

    protected boolean containsDictionary(CharVector cv) {
        /**
         * 2020. 12. 7. 요청사항 형태소 분석시 제조사/브랜드/카테고리 사전 사용하지 않음
         */
        if (extractor.dictionary().find(cv) != null ||
                userDictionary.contains(cv) ||
                (option.useForQuery() && compoundDictionary.containsKey(cv))) {
            return true;
        }
        return false;
    }

    protected boolean isConnected(RuleEntry prevEntry, RuleEntry entry) {
        return entry.start == prevEntry.start + prevEntry.length;
    }

    protected boolean isNotConnected(RuleEntry prevEntry, RuleEntry entry) {
        return entry.start != prevEntry.start + prevEntry.length;
    }

    protected boolean isEntryType(RuleEntry entry, String targetType) {
        return Objects.equals(entry.type, targetType);
    }

    protected boolean isEntryType(RuleEntry entry, String type1, String type2) {
        return Objects.equals(entry.type, type1) || Objects.equals(entry.type, type2);
    }

    protected boolean isEntryType(RuleEntry entry, String type1, String type2, String type3) {
        return Objects.equals(entry.type, type1) || Objects.equals(entry.type, type2) || Objects.equals(entry.type, type3);
    }

    protected boolean isEntryType(RuleEntry entry, String type1, String type2, String type3, String type4) {
        return Objects.equals(entry.type, type1) || Objects.equals(entry.type, type2) || Objects.equals(entry.type, type3) || Objects.equals(entry.type, type4);
    }

    protected boolean isEntryType(RuleEntry entry, String type1, String type2, String type3, String type4, String type5) {
        return Objects.equals(entry.type, type1) || Objects.equals(entry.type, type2) || Objects.equals(entry.type, type3) || Objects.equals(entry.type, type4) || Objects.equals(entry.type, type5);
    }

    protected boolean isNotEntryType(RuleEntry entry, String type1, String type2, String type3, String type4, String type5) {
        return !(Objects.equals(entry.type, type1) || Objects.equals(entry.type, type2) || Objects.equals(entry.type, type3) || Objects.equals(entry.type, type4) || Objects.equals(entry.type, type5));
    }

    protected boolean isEquals(String entryType, String targetType) {
        return Objects.equals(entryType, targetType);
    }

    protected boolean isFullStringEntry(RuleEntry entry) {
        return Objects.equals(entry.type, FULL_STRING);
    }

    protected boolean isNumberEntry(RuleEntry entry) {
        return Objects.equals(entry.type, NUMBER);
    }

    protected boolean isNumberTransEntry(RuleEntry entry) {
        return Objects.equals(entry.type, NUMBER_TRANS);
    }
    protected boolean isUnitEntry(RuleEntry entry) {
        return Objects.equals(entry.type, UNIT);
    }
    protected boolean isUnitAlphaEntry(RuleEntry entry) {
        return Objects.equals(entry.type, UNIT_ALPHA);
    }

    protected boolean isHangulEntry(RuleEntry entry) {
        return Objects.equals(entry.type, HANGUL);
    }

    protected boolean isSymbolEntry(RuleEntry entry) {
        return Objects.equals(entry.type, SYMBOL);
    }

    protected boolean isModelNameEntry(RuleEntry entry) {
        return Objects.equals(entry.type, MODEL_NAME);
    }

    protected boolean isAlphaEntry(RuleEntry entry) {
        return Objects.equals(entry.type, ALPHA);
    }

    protected boolean isJapanese(RuleEntry entry) {
        return Objects.equals(entry.type, JAPANESE);
    }

    protected boolean isChinese(RuleEntry entry) {
        return Objects.equals(entry.type, CHINESE);
    }

    protected boolean isNotFullString(RuleEntry entry) {
        return !Objects.equals(entry.type, FULL_STRING);
    }

    protected boolean isUncategorized(RuleEntry entry) {
        return Objects.equals(entry.type, UNCATEGORIZED);
    }

    protected boolean isNotEquals(String entryType, String targetType) {
        return !Objects.equals(entryType, targetType);
    }

    protected boolean existNextIndex(List<RuleEntry> queue, int qinx) {
        return qinx + 1 < queue.size();
    }

    protected boolean existNextNextIndex(List<RuleEntry> queue, int qinx) {
        return qinx + 2 < queue.size();
    }

    protected boolean isNotSymbol(RuleEntry entry) {
        return !Objects.equals(entry.type, SYMBOL);
    }
}

